<script setup lang="ts">
import{reactive,ref,onMounted,onBeforeUnmount}from'vue';import{api,idemKey}from'../api';import{statusMeta}from'../utils/status';import{useAuthStore}from'../stores/auth';import{ElMessage}from'element-plus';const auth=useAuthStore(),rows=ref<any[]>([]),products=ref<any[]>([]),clusters=ref<any[]>([]),dialog=ref(false),detail=ref<any>(),status=ref(''),timer=ref<number>();const form=reactive<any>({tenantId:2,productId:1,clusterId:1,name:'demo-gpu-instance',quantity:1,scenario:'SUCCESS'});const scenarios=[['SUCCESS','正常成功'],['FAIL','引擎失败并解冻'],['DUPLICATE_CALLBACK','重复回调防重'],['TIMEOUT','超时进入待对账']];const load=async()=>{const data:any=await api.get('/instances',{params:{status:status.value||undefined}});rows.value=data.items};const create=async()=>{await api.post('/instances',{...form,tenantId:auth.isAdmin?form.tenantId:null},{headers:{'Idempotency-Key':idemKey()}});dialog.value=false;ElMessage.success('实例申请已提交，余额已冻结');load()};const retry=async(row:any)=>{await api.post(`/tasks/${row.taskId}/retry`);ElMessage.success('已发起重试或人工对账');load()};onMounted(async()=>{[products.value,clusters.value]=await Promise.all([api.get('/products'),api.get('/clusters')]);load();timer.value=window.setInterval(load,2000)});onBeforeUnmount(()=>clearInterval(timer.value))
</script>
<template><div class="panel"><div class="toolbar"><div><el-select v-model="status" placeholder="全部状态" clearable style="width:150px" @change="load"><el-option v-for="s in ['REQUESTED','DISPATCHING','RUNNING','FAILED','UNKNOWN']" :key="s" :label="statusMeta(s).label" :value="s"/></el-select><el-button @click="load">刷新</el-button></div><el-button v-if="auth.can('instance:create')" type="primary" @click="dialog=true">创建实例</el-button></div><el-table :data="rows"><el-table-column label="实例"><template #default="s"><b>{{s.row.name}}</b><div class="muted">{{s.row.instanceNo}}</div></template></el-table-column><el-table-column label="算力规格"><template #default="s">{{s.row.productName}}<div class="muted">{{s.row.gpuModel}} × {{s.row.gpuCount}}</div></template></el-table-column><el-table-column prop="clusterName" label="目标集群"/><el-table-column label="金额"><template #default="s"><span class="money">¥{{(s.row.amountCent/100).toFixed(2)}}</span></template></el-table-column><el-table-column label="实例状态"><template #default="s"><el-tag :type="statusMeta(s.row.status).type">{{statusMeta(s.row.status).label}}</el-tag></template></el-table-column><el-table-column label="异步任务"><template #default="s"><span>{{statusMeta(s.row.taskState).label}}</span><div class="muted">重试 {{s.row.retryCount}} 次</div></template></el-table-column><el-table-column label="操作" width="135"><template #default="s"><el-button link @click="detail=s.row">详情</el-button><el-button v-if="s.row.status==='UNKNOWN'&&auth.can('instance:retry')" link type="warning" @click="retry(s.row)">对账</el-button></template></el-table-column></el-table></div><el-dialog v-model="dialog" title="创建 GPU 实例" width="560"><el-alert title="提交后将立即冻结对应金额；最终由引擎回调扣款或解冻。" type="info" :closable="false" style="margin-bottom:18px"/><el-form :model="form" label-width="90"><el-form-item v-if="auth.isAdmin" label="租户 ID"><el-input-number v-model="form.tenantId" :min="1"/></el-form-item><el-form-item label="实例名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="算力产品"><el-select v-model="form.productId" style="width:100%"><el-option v-for="p in products" :key="p.id" :label="`${p.name} · ¥${(p.priceCent/100).toFixed(2)}`" :value="p.id"/></el-select></el-form-item><el-form-item label="目标集群"><el-select v-model="form.clusterId" style="width:100%"><el-option v-for="c in clusters" :key="c.id" :label="`${c.name} · ${c.region}`" :value="c.id"/></el-select></el-form-item><el-form-item label="数量"><el-input-number v-model="form.quantity" :min="1" :max="10"/></el-form-item><el-form-item label="演示场景"><el-radio-group v-model="form.scenario"><el-radio v-for="s in scenarios" :key="s[0]" :value="s[0]">{{s[1]}}</el-radio></el-radio-group></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="create">确认并冻结余额</el-button></template></el-dialog><el-drawer v-model="detail" title="实例与任务详情" size="440"><template v-if="detail"><el-descriptions :column="1" border><el-descriptions-item label="实例号">{{detail.instanceNo}}</el-descriptions-item><el-descriptions-item label="订单号">{{detail.orderNo}}</el-descriptions-item><el-descriptions-item label="命令号">{{detail.commandId}}</el-descriptions-item><el-descriptions-item label="引擎实例">{{detail.engineInstanceId||'-'}}</el-descriptions-item><el-descriptions-item label="模拟场景">{{detail.scenario}}</el-descriptions-item><el-descriptions-item label="任务状态">{{detail.taskState}}</el-descriptions-item><el-descriptions-item label="最近错误">{{detail.lastError||'-'}}</el-descriptions-item></el-descriptions><el-timeline style="margin-top:26px"><el-timeline-item timestamp="事务提交" type="primary">冻结余额并写入 Outbox</el-timeline-item><el-timeline-item timestamp="异步投递" :type="detail.status==='REQUESTED'?'info':'primary'">gRPC 命令 {{detail.commandId}}</el-timeline-item><el-timeline-item timestamp="最终结算" :type="detail.status==='RUNNING'?'success':detail.status==='FAILED'?'danger':'warning'">{{statusMeta(detail.status).label}}</el-timeline-item></el-timeline></template></el-drawer></template>
